"""Traditional reflection content, separate from private profile calculations."""
from matching import overview

TITLES = {'sun_sign':'Western zodiac', 'chinese_zodiac':'Chinese zodiac', 'life_path':'Life path', 'name_number':'Name numerology'}
ELEMENTS = {'Aries':'Fire','Leo':'Fire','Sagittarius':'Fire','Taurus':'Earth','Virgo':'Earth','Capricorn':'Earth','Gemini':'Air','Libra':'Air','Aquarius':'Air','Cancer':'Water','Scorpio':'Water','Pisces':'Water'}
ELEMENT_DETAILS = {
 'Fire':('Initiative, enthusiasm and creative expression.','Acting quickly can leave less room for listening or considering consequences.','Share excitement while asking what pace feels comfortable for your partner.'),
 'Earth':('Consistency, practical care and following through.','A preference for certainty can make unfamiliar situations feel uncomfortable.','Discuss routines, responsibilities and how much flexibility each person needs.'),
 'Air':('Curiosity, exchanging ideas and seeing different perspectives.','Analyzing feelings can sometimes take the place of expressing them.','Make room for emotional reassurance as well as stimulating conversation.'),
 'Water':('Emotional awareness, imagination and a sense of belonging.','Sensitivity can make boundaries and direct requests especially helpful.','Ask what care means to each person instead of assuming you feel the same way.')}
NUMBER_CHALLENGES = {1:'Balancing independence with accepting help.',2:'Expressing your own needs while seeking harmony.',3:'Following through when inspiration changes.',4:'Leaving room for flexibility within a plan.',5:'Balancing freedom with consistent commitments.',6:'Caring without taking responsibility for everyone.',7:'Sharing inner thoughts rather than withdrawing.',8:'Balancing achievement with rest and mutual care.',9:'Maintaining boundaries while helping others.',11:'Grounding inspiration in manageable daily choices.',22:'Breaking ambitious plans into realistic steps.',33:'Offering care without neglecting your own limits.'}
ANIMAL_QUESTIONS = {'Monkey':'How do you balance playfulness with reliability?', 'Rooster':'When is attention to detail helpful, and when can you let something be imperfect?', 'Dog':'How do you express loyalty while respecting independence?', 'Pig':'How do you balance generosity with your own boundaries?', 'Rat':'How do you use resourcefulness when plans change?', 'Ox':'Which routines support you, and which could be more flexible?', 'Tiger':'How do courage and patience work together in your relationships?', 'Rabbit':'How do you express disagreement when you want to preserve harmony?', 'Dragon':'How do you make room for another person’s goals alongside your ambitions?', 'Snake':'How do you share your reflections rather than expecting someone to guess?', 'Horse':'How do you balance personal freedom with shared commitments?', 'Goat':'How do you communicate your creative and emotional needs?'}

def symbol_detail(profile, key, private=False):
    if key not in TITLES: raise ValueError('Unknown symbol.')
    o=overview(profile, private=private); value=o[key]
    result={'kind':key, 'title':TITLES[key], 'value':value, 'meaning':o['meanings'][key],
            'perspective':'These are traditional symbolic associations for entertainment and self-reflection. Astrology and numerology have not been shown to create or determine personality. Your experiences, choices, relationships and circumstances matter.',
            'calculation':None}
    if key=='sun_sign':
        strengths,challenge,relationship=ELEMENT_DETAILS[ELEMENTS[value]]
        result.update(method='This app estimates your Western sun sign from the month and day of birth. It does not calculate a full natal chart, Moon sign or ascendant; cusp dates can differ.', personality=f'In Western astrology, {value} is associated with {o["meanings"][key].lower()} Its {ELEMENTS[value]} element is traditionally used to describe a style of motivation and expression.', strengths=strengths, growth=challenge, relationships=relationship, reflection='Which of these themes fits your experience, and which does not?', matching='The symbolic zodiac score compares classical elements: 90 for the same element, 80 for Fire/Air or Earth/Water, and 55 for other pairings. It is a rule output, not a prediction of relationship success.')
    elif key=='chinese_zodiac':
        result.update(method=o['chinese_zodiac_note']+' This app uses the birth year modulo 12, not the Lunar New Year or a complete Chinese astrology chart.', personality=f'In Chinese zodiac symbolism, {value} is associated with {o["meanings"][key].lower()} These themes are used as a cultural storytelling and reflection framework.', strengths=o['meanings'][key], growth='Explore the balance between these themes and the qualities a situation or partner needs; no birth-year animal defines a person.', relationships=ANIMAL_QUESTIONS[value], reflection=ANIMAL_QUESTIONS[value], matching='The birth-year rule gives 90 to animals four or eight positions apart, 45 to opposite animals six positions apart, and 65 otherwise. These are simplified entertainment rules.')
    else:
        label='life-path' if key=='life_path' else 'name'
        result.update(method=('Add every digit in the birth date, then repeatedly sum the digits. Preserve 11, 22 and 33 at each reduction.' if key=='life_path' else 'Normalize the supplied birth name, or first and last names if omitted, to Latin A–Z letters. Assign A=1 through I=9, repeat J=1 through Z=8, sum and reduce while preserving 11, 22 and 33. Names with no supported letters have no number.'), personality=(f'In numerology, the {label} number {value} is associated with {o["meanings"][key].lower()} '+('Life path is traditionally interpreted as a theme for motivations and personal development.' if key=='life_path' else 'The name number is traditionally called an expression or destiny number and interpreted as a theme for self-expression.')) if value else 'A name number is unavailable because the name contains no supported Latin letters.', strengths=o['meanings'][key], growth=NUMBER_CHALLENGES.get(value,'No interpretation is calculated without a supported name number.'), relationships='Use these themes to discuss independence, closeness, responsibilities and how you communicate. Ask your match what actually fits their life.', reflection='Where do you recognize these themes in your choices? What would someone who knows you describe differently?', matching='The life-path component gives 90 for equal life-path numbers and 60 otherwise. Name numbers are shown for reflection and do not affect matching. Love, Living, Money and Communication use stated preferences separately. Different numerology traditions can calculate and interpret numbers differently.')
        if private: result['calculation']=o['breakdown'][key]
    return result
